            </div>
            <span className="font-black text-[15px] tracking-tight uppercase">Recraft.ai</span>
         </div>

         <div className="flex items-center gap-2 group">
            <input 
              value={projectName}
              onChange={(e) => setProjectName(e.target.value)}
              className="bg-transparent border-none text-[13px] font-bold text-zinc-900 focus:outline-none w-40 truncate"
