         </div>
      </div>

      <div className="flex items-center gap-2">
        <div className="flex items-center gap-1 bg-zinc-100/50 p-1 rounded-xl">
            <button 
                onClick={onNewProject}
                className="px-3 py-1.5 hover:bg-white hover:shadow-sm text-zinc-500 hover:text-zinc-900 rounded-lg text-[12px] font-bold transition-all"
