import { useState, useRef, useEffect } from 'react';
import React from 'react';
import { 
  SparklesIcon, 
  SettingsIcon, 
  ArrowIcon,
  CheckIcon,
  PlusIcon,
  XIcon,
  ChevronUpIcon,
  FlaskIcon,
  ZapIcon,
  ImageIcon,
  RectangleHorizontal
} from './Icons';
import { STYLES, ASPECT_RATIOS } from '../constants';
import { ResolutionType, DesignRecipe, Playstyle } from '../types';

interface BottomBarProps {
  lastGenerated: string | null;
  externalRef: string | null;
  onExternalRefConsumed: () => void;
  onGenerate: (prompt: string, style: string, ratio: string, refImages: string[], imageCount: number, artisticLevel: number, resolution: ResolutionType, recipeId?: string, usePro?: boolean) => void;
}

const BottomBar: React.FC<BottomBarProps> = ({ 
  externalRef, 
  onExternalRefConsumed, 
  onGenerate
}) => {
  const [prompt, setPrompt] = useState('');
  const [selectedStyle, setSelectedStyle] = useState(STYLES[0]);
  const [selectedRatio, setSelectedRatio] = useState(ASPECT_RATIOS[0]);
  const [refImages, setRefImages] = useState<string[]>([]);
  const [usePro, setUsePro] = useState(false);

  const [showStyles, setShowStyles] = useState(false);
  const [showRatios, setShowRatios] = useState(false);

  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (externalRef) {
      setRefImages(prev => {
        if (prev.includes(externalRef)) return prev;
        return [...prev, externalRef].slice(-1);
      });
      onExternalRefConsumed();
    }
  }, [externalRef, onExternalRefConsumed]);

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (event) => setRefImages([event.target?.result as string]);
      reader.readAsDataURL(file);
    }
    e.target.value = '';
  };

  const handleSubmit = (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    if (prompt.trim() || refImages.length > 0) {
      onGenerate(prompt.trim() || "Creative design", selectedStyle.id, selectedRatio.id, refImages, 1, 50, '1K', undefined, usePro);
      setPrompt('');
      setRefImages([]);
    }
  };

  return (
    <div className="relative w-full max-w-[720px] bg-white border border-zinc-200/60 shadow-[0_20px_50px_rgba(0,0,0,0.1)] rounded-[24px] p-2 pointer-events-auto flex items-center gap-2 group transition-all hover:shadow-[0_20px_50px_rgba(0,0,0,0.15)]">
      <input type="file" ref={fileInputRef} onChange={handleFileUpload} className="hidden" accept="image/*" />

      {/* Style Picker */}
      <div className="relative">
        <button 
          type="button"
          onClick={() => { setShowStyles(!showStyles); setShowRatios(false); }}
          className={`h-11 px-4 flex items-center gap-2 rounded-xl transition-all ${showStyles ? 'bg-zinc-100 text-black' : 'hover:bg-zinc-50 text-zinc-500'}`}
        >
          <div className="w-5 h-5 rounded-full bg-gradient-to-tr from-indigo-500 to-purple-500 shadow-sm" />
          <span className="text-[12px] font-bold whitespace-nowrap">{selectedStyle.label}</span>
        </button>

        {showStyles && (
            <div className="absolute bottom-full mb-4 left-0 w-60 bg-white border border-zinc-100 rounded-2xl shadow-2xl p-1 flex flex-col gap-0.5 z-[200] animate-in slide-in-from-bottom-2 duration-200">
                <div className="px-3 py-2 text-[10px] font-black text-zinc-400 uppercase tracking-widest border-b border-zinc-50 mb-1">Select Style</div>
                {STYLES.map(s => (
                    <button 
                        key={s.id}
                        type="button"
                        onClick={() => { setSelectedStyle(s); setShowStyles(false); }}
                        className={`px-3 py-2.5 text-[12px] font-bold rounded-lg text-left transition-all ${selectedStyle.id === s.id ? 'bg-zinc-100 text-black' : 'hover:bg-zinc-50 text-zinc-500 hover:text-zinc-900'}`}
                    >
                        {s.label}
                    </button>
                ))}
            </div>
        )}
      </div>

      <div className="w-px h-6 bg-zinc-100" />

      {/* Reference Image Attachment */}
      <div className="flex items-center gap-1">
        {refImages.length > 0 ? (
            <div className="relative group h-10 w-10">
                <img src={refImages[0]} className="h-full w-full object-cover rounded-lg border border-zinc-100" />
                <button 
                    type="button" 
                    onClick={() => setRefImages([])} 
                    className="absolute -top-1.5 -right-1.5 bg-black text-white rounded-full p-0.5 opacity-0 group-hover:opacity-100 transition-opacity"
                >
                    <XIcon className="w-3 h-3" />
                </button>
            </div>
        ) : (
            <button 
                type="button" 
                onClick={() => fileInputRef.current?.click()}
                className="h-10 w-10 flex items-center justify-center text-zinc-400 hover:text-zinc-900 hover:bg-zinc-50 rounded-xl transition-all"
                title="Add reference image"
            >
                <ImageIcon className="w-5 h-5" />
            </button>
        )}
      </div>

      {/* Prompt Input */}
      <input 
        value={prompt}
        onChange={(e) => setPrompt(e.target.value)}
        onKeyDown={(e) => e.key === 'Enter' && handleSubmit()}
        placeholder="Recraft anything..."
        className="flex-1 bg-transparent border-none text-[15px] font-medium text-zinc-900 placeholder-zinc-300 focus:outline-none px-2"
      />

      {/* Aspect Ratio Picker */}
      <div className="relative">
        <button 
          type="button"
          onClick={() => { setShowRatios(!showRatios); setShowStyles(false); }}
          className={`h-11 px-3 flex items-center gap-2 rounded-xl transition-all ${showRatios ? 'bg-zinc-100 text-black' : 'hover:bg-zinc-50 text-zinc-500'}`}
          title="Aspect Ratio"
        >
          <RectangleHorizontal className="w-4.5 h-4.5" />
          <span className="text-[11px] font-bold font-mono">{selectedRatio.id}</span>
        </button>

        {showRatios && (
            <div className="absolute bottom-full mb-4 right-0 w-44 bg-white border border-zinc-100 rounded-2xl shadow-2xl p-1 flex flex-col gap-0.5 z-[200] animate-in slide-in-from-bottom-2 duration-200">
                <div className="px-3 py-2 text-[10px] font-black text-zinc-400 uppercase tracking-widest border-b border-zinc-50 mb-1">Canvas Ratio</div>
                {ASPECT_RATIOS.map(r => (
                    <button 
                        key={r.id}
                        type="button"
                        onClick={() => { setSelectedRatio(r); setShowRatios(false); }}
                        className={`px-3 py-2.5 text-[12px] font-bold rounded-lg text-left transition-all ${selectedRatio.id === r.id ? 'bg-zinc-100 text-black' : 'hover:bg-zinc-50 text-zinc-500 hover:text-zinc-900'}`}
                    >
                        {r.label} ({r.id})
                    </button>
                ))}
            </div>
        )}
      </div>

      {/* Submit Button */}
      <button 
        onClick={() => handleSubmit()}
        disabled={!prompt.trim() && refImages.length === 0}
        className={`h-11 px-6 rounded-xl font-black text-[13px] uppercase tracking-widest transition-all active:scale-95 ${(!prompt.trim() && refImages.length === 0) ? 'bg-zinc-100 text-zinc-300 cursor-not-allowed' : 'bg-black text-white hover:bg-zinc-800 shadow-lg shadow-black/10'}`}
      >
        Recraft
      </button>
    </div>
  );
};

export default BottomBar;

import { useRef, useState, useImperativeHandle, forwardRef, useMemo, useEffect, useCallback } from 'react';
import React from 'react';
import { CanvasItem, ViewState, Point, ToolType, ItemType, EditToolType, Segment, IdentifiedPoint, Rect, ExpressionState, SpatialConfig, PartCMF, BOMEntry } from '../types';
import { 
    RotateCcwIcon, SparklesIcon, XIcon,
    TrashIcon, CameraIcon, PenIcon, BoxIcon, LinkIcon, MessageCircleIcon,
    LanguagesIcon, ArrowIcon, SquareIcon, CircleIcon, BrushIcon, ScanIcon, RefreshIcon, EyeOffIcon, PaletteIcon, TargetIcon, ListOrderedIcon, ChevronDownIcon, MousePointer2
} from './Icons';
import MaskCanvas, { MaskCanvasRef } from './MaskCanvas';
import FloatingSelectionBar from './FloatingSelectionBar';
import ExpressionController from './ExpressionController';
import VolumeInferencePanel from './VolumeInferencePanel';
import AntigravityLoading from './AntigravityLoading';
import ModelViewport from './ModelViewport';
import { useCanvasMath } from '../hooks/useCanvasMath';
import { useTransformEngine } from '../hooks/useTransformEngine';
import { useAnnotations, Annotation } from '../hooks/useAnnotations';
import { useCaptureManager } from '../hooks/useCaptureManager';
import { useFeaturePointInteraction } from '../hooks/useFeaturePointInteraction';

interface CanvasProps {
  items: CanvasItem[];
  selection: string[];
  tool: ToolType;
  view: ViewState;
  setView: (view: ViewState | ((prev: ViewState) => ViewState)) => void;
  setSelection: (ids: string[]) => void;
  addItem: (item: CanvasItem) => void;
  updateItem: (id: string, updates: Partial<CanvasItem>) => void;
  updateItems?: (updates: { id: string, updates: Partial<CanvasItem> }[]) => void;
  onContextMenu?: (e: React.MouseEvent, itemId?: string) => void;
  onDelete?: (id: string) => void;
  editMode?: boolean;
  editTool?: EditToolType;
  brushSize?: number;
  segments?: Segment[];
  onApplyEdit?: (prompt: string) => void;
  onSelectItem?: (id: string) => void;
  onPointPicked?: (itemId: string, y: number, x: number) => void;
  isPickingPoint?: boolean;
  showPointLabels?: boolean;
  onDeletePointLocal?: (itemId: string, pointId: string) => void;
  onMovePoint?: (itemId: string, pointId: string, ny: number, nx: number) => void;
  onMovePointEnd?: (itemId: string, pointId: string, from: [number, number], to: [number, number]) => void;
  showGrid?: boolean;
  onZoomToFit?: () => void;
  onCaptureRegion?: (region: Rect, action: 'chat' | 'canvas' | 'translate', capturedImage?: string | null, annotations?: Annotation[]) => void;
  onFloatingAction?: (id: string, action: string) => void;
  expressionState: ExpressionState;
  setExpressionState: (state: ExpressionState) => void;
  inferenceState: { itemId: string, isOpen: boolean };
  setInferenceState: (state: { itemId: string, isOpen: boolean }) => void;
  currentEvolutionLevel?: number;
  captureState?: ReturnType<typeof useCaptureManager>;
  onExitToolMode?: () => void;
  activePartId?: string;
  onPartSelect?: (partId: string) => void;
  onCameraChange?: (id: string, spatial: SpatialConfig) => void;
  onLoadParts?: (id: string, parts: string[]) => void;
}

export interface CanvasRef { 
    getMaskData: () => Promise<{ cutout: string, mask: string } | null>;
    clearMask: () => void;
}

const Canvas = forwardRef<CanvasRef, CanvasProps>(({ 
  items, selection, tool, view, setView, setSelection, addItem, updateItem,
  onContextMenu, editMode, editTool = 'brush', brushSize = 30,
  onSelectItem, onPointPicked, isPickingPoint, 
  showPointLabels = true, onDeletePointLocal, onMovePoint, onMovePointEnd,
  showGrid = true, onZoomToFit, onCaptureRegion, onFloatingAction,
  expressionState, setExpressionState, inferenceState, setInferenceState, currentEvolutionLevel = 60,
  captureState, onExitToolMode, activePartId, onPartSelect, onCameraChange, onLoadParts
}, ref) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const maskCanvasRef = useRef<MaskCanvasRef>(null);

  const { screenToCanvas, handleScale, handleSize, borderWidth, rotateHandleSize, rotateHandleOffset, rotateIconSize, snapThreshold } = useCanvasMath(view, containerRef);
  const { transforming, snapLines, startTransform, updateTransform, endTransform } = useTransformEngine(items, updateItem, snapThreshold);
  const { annotations, activeTool: activeAnnoTool, setActiveTool: setActiveAnnoTool, isDrawing: isDrawingAnno, addAnnotation, updateCurrentAnnotation, stopDrawing: stopDrawingAnno, clearAnnotations } = useAnnotations();
  const captureManager = useCaptureManager();

  const { isCapturing, captureRect, showCaptureMenu, capturedImage, isGrabbingStream, beginCapture, updateCapture, finishCapture, resetCapture, grabScreenPixels } = captureState || captureManager;

  const { draggingPoint, hoveredPointId, setHoveredPointWithDelay, handleStartDrag, handleDragUpdate, handleDragEnd, hoverTimeoutRef } = useFeaturePointInteraction(onMovePoint, onMovePointEnd);

  const [isPanning, setIsPanning] = useState(false);
  const [panStart, setPanStart] = useState<Point>({ x: 0, y: 0 });
  const [isMarquee, setIsMarquee] = useState(false);
  const [marqueeStart, setMarqueeStart] = useState<Point>({ x: 0, y: 0 });
  const [marqueeEnd, setMarqueeEnd] = useState<Point>({ x: 0, y: 0 });
  const [mouseCanvasPos, setMouseCanvasPos] = useState<Point>({ x: 0, y: 0 });
  const [spacePressed, setSpacePressed] = useState(false);

  useEffect(() => {
    const container = containerRef.current;
    if (!container) return;
    const handleWheel = (e: WheelEvent) => {
      if (isPanning) return;
      const target = e.target as HTMLElement;
      if (target.closest('.model-viewport-container')) return;
      e.preventDefault(); 
      const delta = -e.deltaY;
      const zoomFactor = Math.pow(1.15, delta / 120); 
      setView((prev) => {
        const newScale = Math.min(Math.max(prev.scale * zoomFactor, 0.01), 50);
        const rect = container.getBoundingClientRect();
        const mouseX = e.clientX - rect.left;
        const mouseY = e.clientY - rect.top;
        const newX = mouseX - (mouseX - prev.x) * (newScale / prev.scale);
        const newY = mouseY - (mouseY - prev.y) * (newScale / prev.scale);
        return { scale: newScale, x: newX, y: newY };
      });
    };
    container.addEventListener('wheel', handleWheel, { passive: false });
    return () => container.removeEventListener('wheel', handleWheel);
  }, [setView, isPanning]);

  useEffect(() => {
    const hk = (e: KeyboardEvent) => { if (e.key === ' ' && !['INPUT', 'TEXTAREA'].includes((e.target as HTMLElement).tagName)) setSpacePressed(true); };
    const hku = (e: KeyboardEvent) => { if (e.key === ' ') setSpacePressed(false); };
    window.addEventListener('keydown', hk); window.addEventListener('keyup', hku);
    return () => { window.removeEventListener('keydown', hk); window.removeEventListener('keyup', hku); if (hoverTimeoutRef.current) window.clearTimeout(hoverTimeoutRef.current); };
  }, []);

  useImperativeHandle(ref, () => ({ 
    getMaskData: async () => { if (!maskCanvasRef.current) return null; const cutout = await maskCanvasRef.current.getMaskedImage(); const mask = await maskCanvasRef.current.getSelectionMask(); return (cutout && mask) ? { cutout, mask } : null; },
    clearMask: () => maskCanvasRef.current?.clearMask()
  }));

  const handleMouseDown = (e: React.MouseEvent) => {
    const pos = screenToCanvas(e.clientX, e.clientY);
    if (e.button === 2) { e.preventDefault(); onExitToolMode?.(); return; }
    if (e.button === 1) { 
        e.preventDefault(); setIsPanning(true); setPanStart({ x: e.clientX - view.x, y: e.clientY - view.y }); return; 
    }
    if (tool === 'hand' || spacePressed) { e.preventDefault(); setIsPanning(true); setPanStart({ x: e.clientX - view.x, y: e.clientY - view.y }); return; }
    if (tool === 'capture') {
        if (showCaptureMenu && activeAnnoTool !== 'none' && captureRect && pos.x >= captureRect.x && pos.x <= captureRect.x + captureRect.width && pos.y >= captureRect.y && pos.y <= captureRect.y + captureRect.height) {
            if (activeAnnoTool === 'number') addAnnotation('number', pos, (annotations.filter(a => a.type === 'number').length + 1).toString());
            else if (['arrow', 'rectangle', 'circle', 'brush'].includes(activeAnnoTool)) addAnnotation(activeAnnoTool as any, pos);
            return;
        }
        clearAnnotations(); beginCapture(pos); return;
    }
    if (editMode) return;
    const isBg = (e.target as HTMLElement).id === 'canvas-bg' || (e.target as HTMLElement).id === 'dot-grid';
    if (isBg && tool === 'select' && e.button === 0) { setIsMarquee(true); setMarqueeStart(pos); setMarqueeEnd(pos); if (!e.shiftKey) setSelection([]); }
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    const pos = screenToCanvas(e.clientX, e.clientY); setMouseCanvasPos(pos);
    if (draggingPoint) handleDragUpdate(pos, items);
    else if (isPanning) setView({ ...view, x: e.clientX - panStart.x, y: e.clientY - panStart.y });
    else if (isCapturing) updateCapture(pos);
    else if (isDrawingAnno) updateCurrentAnnotation(pos);
    else if (isMarquee) { setMarqueeEnd(pos); const x1 = Math.min(marqueeStart.x, pos.x), y1 = Math.min(marqueeStart.y, pos.y), x2 = Math.max(marqueeStart.x, pos.x), y2 = Math.max(marqueeStart.y, pos.y); setSelection(items.filter(i => i.x >= x1 && i.x + i.width <= x2 && i.y >= y1 && i.y + i.height <= y2).map(i => i.id)); }
    else if (transforming) updateTransform(pos);
  };

  const handleMouseUp = (e: React.MouseEvent) => {
    const pos = screenToCanvas(e.clientX, e.clientY);
    if (draggingPoint) handleDragEnd(pos, items);
    if (isCapturing) finishCapture();
    if (isDrawingAnno) stopDrawingAnno();
    setIsPanning(false); setIsMarquee(false); endTransform();
  };

  const sortedItems = useMemo(() => [...items].sort((a, b) => (a.type === ItemType.FRAME ? -1 : 1)), [items]);

  const floatingUIConfig = useMemo(() => {
    if (selection.length === 0) return null;
    const selectedItemsList = items.filter(i => selection.includes(i.id));
    const minL_Y = Math.min(...selectedItemsList.map(it => it.y));
    const maxL_Y = Math.max(...selectedItemsList.map(it => it.y + it.height));
    const minL_X = Math.min(...selectedItemsList.map(it => it.x));
    const maxL_X = Math.max(...selectedItemsList.map(it => it.x + it.width));
    const centerX = minL_X + (maxL_X - minL_X) / 2;
    const screenX = centerX * view.scale + view.x;
    const screenY_Top = minL_Y * view.scale + view.y;
    const screenY_Bottom = maxL_Y * view.scale + view.y;
    const isNearTop = screenY_Top < 140;
    return { screenX, screenY: isNearTop ? screenY_Bottom + 24 : screenY_Top - 24, isNearTop, expressionItem: selection.length === 1 ? selectedItemsList[0] : null };
  }, [selection, items, view.scale, view.x, view.y]);

  const executeCaptureAction = async (action: 'chat' | 'canvas' | 'translate') => {
      if (!captureRect) return;
      let finalImg = capturedImage;
      if (!finalImg) finalImg = await grabScreenPixels(captureRect, view.scale, view.x, view.y);
      onCaptureRegion?.(captureRect, action, finalImg, annotations);
      resetCapture();
  };

  return (
    <div ref={containerRef} onMouseDown={handleMouseDown} onMouseMove={handleMouseMove} onMouseUp={handleMouseUp} onContextMenu={e => { e.preventDefault(); onContextMenu?.(e); }} id="canvas-bg" className={`relative w-full h-full overflow-hidden select-none bg-white ${spacePressed || isPanning ? 'cursor-grabbing' : (tool === 'hand' ? 'cursor-grab' : '')} ${tool === 'capture' ? 'cursor-crosshair' : ''}`}>
      {showGrid && <div id="dot-grid" className="dot-grid absolute inset-0 pointer-events-none" style={{ backgroundPosition: `${view.x}px ${view.y}px`, backgroundSize: `${24*view.scale}px ${24*view.scale}px` }} />}

      <div className="origin-top-left absolute" style={{ transform: `translate(${view.x}px, ${view.y}px) scale(${view.scale})` }}>
        {sortedItems.map(item => {
          const isSel = selection.includes(item.id);
          const isBeingTransformed = transforming?.initialItems.some(ti => ti.id === item.id);
          const isFrame = item.type === ItemType.FRAME;

          return (
            <div key={item.id} data-item-id={item.id} className={`absolute group ${isSel ? 'z-50' : (isFrame ? 'z-0' : 'z-10')} ${isBeingTransformed ? 'pointer-events-none' : ''}`} style={{ left: item.x, top: item.y, width: item.width, height: item.height, transform: `rotate(${item.rotation || 0}deg)`, opacity: isBeingTransformed ? 0.6 : 1 }} onDoubleClick={() => onSelectItem?.(item.id)}>
              <div 
                onMouseDown={e => { 
                    if (e.button !== 0 || editMode) return; 
                    e.stopPropagation(); 
                    const ns = e.shiftKey ? [...selection, item.id] : (selection.includes(item.id) ? selection : [item.id]); 
                    setSelection(ns); 
                    startTransform('drag', mouseCanvasPos, ns); 
                }} 
                className={`w-full h-full relative rounded-lg overflow-hidden transition-shadow ${isSel ? 'shadow-[0_0_0_2px_#000]' : (isFrame ? 'bg-zinc-50 border border-zinc-100' : 'bg-transparent')}`} 
              >
                {item.type === ItemType.IMAGE && (item.content ? <img src={item.content} className="w-full h-full object-contain pointer-events-none" /> : (
                  <div className="w-full h-full flex items-center justify-center bg-white">
                    {item.status === 'loading' && <AntigravityLoading width={item.width} height={item.height} mousePos={{ x: mouseCanvasPos.x - item.x, y: mouseCanvasPos.y - item.y }} />}
                  </div>
                ))}
                {item.type === ItemType.MODEL && item.modelUrl && (
                  <div className="w-full h-full model-viewport-container" onMouseDown={e => e.stopPropagation()} onMouseMove={e => e.stopPropagation()} onMouseUp={e => e.stopPropagation()}>
                    <ModelViewport 
                        url={item.modelUrl} viewAngle={item.viewAngle} explodeFactor={item.explodeFactor} knollingFactor={item.knollingFactor} activePartId={activePartId} partCMFMap={item.partCMFMap} wireframeMode={item.wireframeMode} onPartSelect={onPartSelect} onCameraChange={(s) => onCameraChange?.(item.id, s)} width={item.width} height={item.height} spatialConfig={item.spatialConfig} cameraMode={item.cameraMode}
                    />
                  </div>
                )}
                {item.type === ItemType.TEXT && (
                    <div className="w-full h-full flex items-center justify-center p-4">
                         <p className="text-center w-full break-words outline-none select-none font-bold" style={{ fontSize: `${item.fontSize || 24}px`, color: item.textColor || '#18181b' }}>{item.content}</p>
                    </div>
                )}
              </div>
              {isSel && !editMode && !isBeingTransformed && (tool === 'select') && ( 
                <> 
                    {['top-left', 'top-right', 'bottom-left', 'bottom-right'].map(h => ( <div key={h} onMouseDown={e => { e.stopPropagation(); startTransform('resize', mouseCanvasPos, [item.id], h); }} className="absolute bg-white z-[90] shadow-md border border-black rounded-sm" style={{ width: `${handleSize}px`, height: `${handleSize}px`, left: h.includes('left') ? 0 : '100%', top: h.includes('top') ? 0 : '100%', transform: 'translate(-50%, -50%)' }} /> ))} 
                </> 
              )}
            </div>
          );
        })}
      </div>

      <div className="absolute inset-0 pointer-events-none z-[1000]">
        {floatingUIConfig && !editMode && !transforming && tool === 'select' && (
          <div className="absolute left-0 top-0" style={{ transform: `translate3d(${floatingUIConfig.screenX}px, ${floatingUIConfig.screenY}px, 0) translate(-50%, ${floatingUIConfig.isNearTop ? '0' : '-100%'})`, willChange: 'transform' }}>
            <FloatingSelectionBar items={items.filter(i => selection.includes(i.id))} onAction={a => onFloatingAction?.(selection[0], a)} />
          </div>
        )}

        {showCaptureMenu && captureRect && (
          <div className="absolute p-1 bg-white border border-zinc-100 rounded-xl shadow-2xl pointer-events-auto flex items-center gap-1" style={{ left: (captureRect.x + captureRect.width) * view.scale + view.x + 10, top: (captureRect.y + captureRect.height) * view.scale + view.y, transform: 'translateY(-50%)' }}>
                <button onClick={() => executeCaptureAction('canvas')} className="px-4 py-2 bg-black text-white rounded-lg text-[12px] font-black uppercase tracking-widest hover:bg-zinc-800 transition-all shadow-xl">Recraft Area</button>
                <button onClick={resetCapture} className="p-2 text-zinc-400 hover:text-red-500 rounded-lg transition-all"><XIcon className="w-5 h-5" /></button>
          </div>
        )}
      </div>

      {isCapturing && captureRect && (
        <div className="absolute border-2 border-black bg-black/5 z-[100] ring-[2000px] ring-white/40" style={{ left: captureRect.x * view.scale + view.x, top: captureRect.y * view.scale + view.y, width: captureRect.width * view.scale, height: captureRect.height * view.scale }} />
      )}

      {isMarquee && <div className="absolute border border-black bg-black/5 z-[100]" style={{ left: Math.min(marqueeStart.x, marqueeEnd.x) * view.scale + view.x, top: Math.min(marqueeStart.y, marqueeEnd.y) * view.scale + view.y, width: Math.abs(marqueeStart.x - marqueeEnd.x) * view.scale, height: Math.abs(marqueeStart.y - marqueeEnd.y) * view.scale }} />}

      <svg className="absolute inset-0 pointer-events-none z-30" style={{ transform: `translate(${view.x}px, ${view.y}px) scale(${view.scale})` }}>
          {snapLines.map((line, i) => ( <line key={i} x1={line.x ?? -10000} y1={line.y ?? -10000} x2={line.x ?? 10000} y2={line.y ?? 10000} stroke="#e2e2e7" strokeWidth={1/view.scale} /> ))}
      </svg>
    </div>
  );
});

export default Canvas;

import { useState, useEffect, useRef, useCallback } from 'react';
import React from 'react';
import Canvas, { CanvasRef } from './components/Canvas';
import LeftToolbar from './components/LeftToolbar';
import LayersPanel from './components/LayersPanel';
import HistoryPanel from './components/HistoryPanel';
import PropertiesPanel from './components/PropertiesPanel';
import ContextMenu from './components/ContextMenu';
import BottomBar from './components/BottomBar';
import GeminiChatPanel, { GeminiChatPanelRef } from './components/GeminiChatPanel';
import DesignRecipePanel from './components/DesignRecipePanel';
import TopBar from './components/TopBar';
import { CanvasItem, ToolType, ViewState, ItemType, EditToolType, GenerationSettings, Segment, IdentifiedPoint, Rect, ExpressionState, DesignRecipe, ProjectPackage, ResolutionType, SpatialConfig } from './types';
import { generateImage, analyzeImageForPrompt, generateWithReferences, editImage, detectImageJSONSegments } from './services/geminiService';
import { useAssetManager } from './hooks/useAssetManager';
import { useHistory } from './hooks/useHistory';
import { useProjectPersistence } from './hooks/useProjectPersistence';
import { useCaptureManager } from './hooks/useCaptureManager';
import { useAnnotations } from './hooks/useAnnotations';
import { STYLES, ASPECT_RATIOS } from './constants';
import { MinusIcon, PlusIcon, MaximizeIcon } from './components/Icons';

const App: React.FC = () => {
  const { items, setItems, commit, undo, redo, resetHistory } = useHistory([]);
  const [selection, setSelection] = useState<string[]>([]);
  const [view, setView] = useState<ViewState>({ x: 0, y: 0, scale: 1 });

  const { handleFile, handlePaste, findPlacementSpot, getImageDimensions } = useAssetManager({
    view, items, setItems, setSelection
  });

  useProjectPersistence(items, (loadedItems) => { resetHistory(loadedItems); });

  const [tool, setTool] = useState<ToolType>('select');
  const [showLayers, setShowLayers] = useState(false);
  const [showHistory, setShowHistory] = useState(false);
  const [contextMenu, setContextMenu] = useState<{ isOpen: boolean; x: number; y: number; itemId?: string } | null>(null);
  const [externalRefImage, setExternalRefImage] = useState<string | null>(null);
  const [isPropertiesPanelOpen, setIsPropertiesPanelOpen] = useState(false);
  const [showGrid, setShowGrid] = useState(true);
  const [editMode, setEditMode] = useState(false);
  const [expressionState, setExpressionState] = useState<ExpressionState>({ itemId: '', isOpen: false });
  const [inferenceState, setInferenceState] = useState({ itemId: '', isOpen: false });

  const captureState = useCaptureManager();
  const [recipePanelData, setRecipePanelData] = useState<{ images: string[], instruction: string } | null>(null);

  const canvasRef = useRef<CanvasRef>(null);
  const chatRef = useRef<GeminiChatPanelRef>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const selectedItem = selection.length === 1 ? items.find(it => it.id === selection[0]) || null : null;

  const handleUpdateItem = useCallback((id: string, updates: Partial<CanvasItem>) => setItems(prev => prev.map(item => item.id === id ? { ...item, ...updates } : item)), [setItems]);
  const handleDeleteItems = useCallback((ids: string[]) => { const nextItems = items.filter(item => !ids.includes(item.id)); setItems(nextItems); commit(nextItems); setSelection([]); }, [items, setItems, commit]);

  const zoomToFit = useCallback(() => {
    if (items.length === 0) { setView({ x: 0, y: 0, scale: 1 }); return; }
    const minX = Math.min(...items.map(i => i.x)), minY = Math.min(...items.map(i => i.y));
    const maxX = Math.max(...items.map(i => i.x + i.width)), maxY = Math.max(...items.map(i => i.y + i.height));
    const scale = Math.min((window.innerWidth - 400) / (maxX - minX), (window.innerHeight - 200) / (maxY - minY), 1.5);
    setView({ scale, x: window.innerWidth / 2 - (minX + (maxX - minX) / 2) * scale, y: window.innerHeight / 2 - (minY + (maxY - minY) / 2) * scale });
  }, [items, setView]);

  const handleGenerate = async (id: string, promptText: string, settings?: Partial<GenerationSettings>, manualRefs?: string[]) => {
    const targetW = 512, targetH = 512;
    const nid = crypto.randomUUID();
    const spot = findPlacementSpot(targetW, targetH, items);
    const placeholder: CanvasItem = { id: nid, type: ItemType.IMAGE, x: spot.x, y: spot.y, width: targetW, height: targetH, rotation: 0, content: '', status: 'loading', prompt: promptText, aspectRatio: settings?.ratio || '1:1' };
    const nextItems = [...items, placeholder];
    setItems(nextItems); commit(nextItems); setSelection([nid]);

    try {
        let url: string;
        const styleObj = STYLES.find(s => s.id === settings?.style) || STYLES[0];
        if (manualRefs && manualRefs.length > 0) {
            url = await generateWithReferences(promptText, manualRefs.map(r => ({ label: 'ref', base64: r })), settings?.ratio || '1:1', styleObj.promptSuffix);
        } else {
            url = await generateImage(promptText, styleObj.promptSuffix, settings?.ratio || '1:1', settings?.artisticLevel || 50, settings?.resolution || '1K', undefined, undefined, settings?.usePro);
        }
        const { width, height } = await getImageDimensions(url);
        setItems(prev => prev.map(i => i.id === nid ? { ...i, content: url, status: 'generated', height: (height * i.width) / width } : i));
    } catch (e) { setItems(prev => prev.map(i => i.id === nid ? { ...i, status: 'error' } : i)); }
  };

  const handleCloudSave = async () => { alert("Cloud save placeholder activated"); };
  const handleCloudLoad = async () => { alert("Cloud load placeholder activated"); };

  return (
    <div className="w-screen h-screen bg-white overflow-hidden flex flex-col font-sans relative" onDragOver={e => e.preventDefault()} onDrop={e => { e.preventDefault(); Array.from(e.dataTransfer.files).forEach(f => handleFile(f)); }}>
      <TopBar onExport={() => {}} onImport={handleFile} onCloudExport={handleCloudSave} onCloudImport={handleCloudLoad} onNewProject={() => { if(confirm("New project?")) setItems([]); }} />

      <LeftToolbar activeTool={tool} setTool={setTool} onUpload={() => fileInputRef.current?.click()} onToggleLayers={() => setShowLayers(!showLayers)} showLayers={showLayers} onToggleHistory={() => setShowHistory(!showHistory)} showHistory={showHistory} recordingStatus="idle" onStartRecording={() => {}} onStopRecording={() => {}} />

      <LayersPanel isOpen={showLayers} items={items} selection={selection[0] || null} onSelectItem={id => setSelection([id])} onUpdateItem={handleUpdateItem} />
      <HistoryPanel isOpen={showHistory} onClose={() => setShowHistory(false)} onRestore={snap => resetHistory(snap.items)} />

      <div className="w-full h-full pt-14">
        <Canvas ref={canvasRef} items={items} selection={selection} tool={tool} view={view} setView={setView} setSelection={setSelection} addItem={it => setItems(prev => [...prev, it])} updateItem={handleUpdateItem} onContextMenu={(e, id) => setContextMenu({ isOpen: true, x: e.clientX, y: e.clientY, itemId: id })} onDelete={id => handleDeleteItems([id])} editMode={editMode} showGrid={showGrid} onZoomToFit={zoomToFit} expressionState={expressionState} setExpressionState={setExpressionState} inferenceState={inferenceState} setInferenceState={setInferenceState} captureState={captureState} onExitToolMode={() => setTool('select')} />
      </div>

      <div className="fixed bottom-6 left-6 z-50 flex items-center bg-white/90 backdrop-blur-xl border border-zinc-100 p-1 rounded-2xl shadow-lg">
        <button onClick={() => setView(v => ({ ...v, scale: v.scale / 1.2 }))} className="w-10 h-10 flex items-center justify-center text-zinc-500 hover:text-black hover:bg-zinc-50 rounded-xl transition-all"><MinusIcon className="w-4 h-4" /></button>
        <div className="px-3 min-w-[60px] text-center"><span className="text-[11px] font-black font-mono">{Math.round(view.scale * 100)}%</span></div>
        <button onClick={() => setView(v => ({ ...v, scale: v.scale * 1.2 }))} className="w-10 h-10 flex items-center justify-center text-zinc-500 hover:text-black hover:bg-zinc-50 rounded-xl transition-all"><PlusIcon className="w-4 h-4" /></button>
        <div className="w-px h-6 bg-zinc-100 mx-1" />
        <button onClick={zoomToFit} className="w-10 h-10 flex items-center justify-center text-zinc-500 hover:text-black hover:bg-zinc-50 rounded-xl transition-all"><MaximizeIcon className="w-4 h-4" /></button>
      </div>

      <div className="fixed bottom-10 left-1/2 -translate-x-1/2 z-[70] pointer-events-none flex flex-col items-center gap-4">
        <BottomBar lastGenerated={null} externalRef={externalRefImage} onExternalRefConsumed={() => setExternalRefImage(null)} onGenerate={(p, s, r, refs) => handleGenerate('', p, { style: s, ratio: r }, refs)} />
      </div>

      <div className={`fixed right-4 top-20 bottom-4 flex flex-col transition-all duration-300 ${isPropertiesPanelOpen || selectedItem ? 'w-80' : 'w-0 overflow-hidden'}`}>
        <PropertiesPanel selectedItem={selectedItem} onUpdateItem={handleUpdateItem} onGenerate={handleGenerate} onDelete={id => handleDeleteItems([id])} isCncMode={false} setIsCncMode={() => {}} />
      </div>

      {contextMenu && <ContextMenu x={contextMenu.x} y={contextMenu.y} selectedItem={items.find(i => i.id === contextMenu.itemId) || null} onSelect={() => setContextMenu(null)} onClose={() => setContextMenu(null)} />}

      <GeminiChatPanel ref={chatRef} onAddToCanvas={(url) => handleFile(url)} />
      <input type="file" ref={fileInputRef} onChange={e => Array.from(e.target.files || []).forEach(handleFile)} className="hidden" accept="image/*,video/*,.obj" />
    </div>
  );
};
export default App;

import { useRef, useState, useImperativeHandle, forwardRef, useMemo, useEffect, useCallback } from 'react';
import React from 'react';
import { CanvasItem, ViewState, Point, ToolType, ItemType, EditToolType, Segment, IdentifiedPoint, Rect, ExpressionState, SpatialConfig, PartCMF, BOMEntry } from '../types';
import { 
    RotateCcwIcon, SparklesIcon, XIcon,
    TrashIcon, CameraIcon, PenIcon, BoxIcon, LinkIcon, MessageCircleIcon,
    LanguagesIcon, ArrowIcon, SquareIcon, CircleIcon, BrushIcon, ScanIcon, RefreshIcon, EyeOffIcon, PaletteIcon, TargetIcon, ListOrderedIcon, ChevronDownIcon
