        const ai = getAI(); const spatialTxt = getSpatialInstructions(spatial);
        const model = usePro ? 'gemini-3-pro-image-preview' : 'gemini-2.5-flash-image';
        const config: any = { 
            imageConfig: { aspectRatio: normalizeAspectRatio(ratio) }, 
            temperature: artisticScale / 50.0 
        };
        if (usePro) config.imageConfig.imageSize = resolution;

        const response = await ai.models.generateContent({ 
            model, 
            contents: [{ parts: [{ text: `${prompt}. ${spatialTxt} ${recipeInstruction || ''}. Style: ${styleSuffix}. 1k resolution.` }] }], 
            config 
        });
        const part = response.candidates?.[0]?.content?.parts?.find(p => p.inlineData); if (part?.inlineData) return `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
        throw new Error("Image failed.");
    });
};

