  return (
    <div className="w-screen h-screen bg-[#f4f4f5] dark:bg-[#09090b] overflow-hidden flex flex-col font-sans relative" onDragOver={(e) => { e.preventDefault(); e.stopPropagation(); }} onDrop={(e) => { e.preventDefault(); e.stopPropagation(); const files = Array.from(e.dataTransfer.files); if (files.length > 0) files.forEach(f => handleFile(f)); else { const url = e.dataTransfer.getData('text/plain'); if (url) handleFile(url); } }}>
      <TopBar onExport={handleExportProject} onImport={handleImportProject} onCloudExport={handleCloudSave} onCloudImport={handleCloudLoad} onNewProject={() => { if (window.confirm("确定要新建画布吗？")) { resetHistory([]); setView({ x: 0, y: 0, scale: 1 }); setSelection([]); } }} />
      <LeftToolbar activeTool={tool} setTool={setTool} onUpload={() => fileInputRef.current?.click()} onToggleLayers={() => setShowLayers(!showLayers)} showLayers={showLayers} onToggleHistory={() => setShowHistory(!showHistory)} showHistory={showHistory} onAddFrame={() => { const spot = findPlacementSpot(800, 600, items); const f: CanvasItem = { id: crypto.randomUUID(), type: ItemType.FRAME, x: spot.x, y: spot.y, width: 800, height: 600, rotation: 0, content: 'New Frame', status: 'empty' }; const nextItems = [...items, f]; setItems(nextItems); commit(nextItems); setSelection([f.id]); }} recordingStatus={recordingStatus} onStartRecording={startRecording} onStopRecording={stopRecording} onPauseRecording={() => {}} onResumeRecording={() => {}} recordingTime={recordingTime} />
      <LayersPanel isOpen={showLayers} items={items} selection={selection.length > 0 ? selection[0] : null} onSelectItem={(id) => { setSelection([id]); const item = items.find(i => i.id === id); if (item) centerOnItem(item); }} onUpdateItem={handleUpdateItem} />
      <HistoryPanel isOpen={showHistory} onClose={() => setShowHistory(false)} onRestore={(snap) => { resetHistory(snap.items); setSelection([]); }} />
      <div className="w-full h-full">
        <Canvas ref={canvasRef} items={items} selection={selection} tool={tool} view={view} setView={setView} setSelection={setSelection} addItem={it => { const nextItems = [...items, it]; setItems(nextItems); commit(nextItems); }} updateItem={handleUpdateItem} updateItems={handleUpdateItems} onContextMenu={(e, id) => { if (tool === 'point' || tool === 'capture') return; const sid = id || (selection.length === 1 ? selection[0] : undefined); setContextMenu({ isOpen: true, x: e.clientX, y: e.clientY, itemId: sid }); }} onDelete={id => handleDeleteItems([id])} editMode={editMode} editTool={editTool} brushSize={brushSize} brushColor={brushColor} segments={segments} onApplyEdit={handleApplyEdit} onSelectItem={(id) => { const item = items.find(it => id === it.id); if (item && (item.type === ItemType.IMAGE || item.type === ItemType.VIDEO || item.type === ItemType.MODEL) && (item.content || item.modelUrl)) { if (isPickingPoint && pickingTargetId === item.id) return; if (tool === 'point' || tool === 'capture') return; setQuickLookItem(item); } }} onPointPicked={handlePickPoint} isPickingPoint={isPickingPoint && !!pickingTargetId} onPointTagClick={(it, pt) => chatRef.current?.addPointReference(it.id, it.content || '', pt.label, [pt.y, pt.x])} onPointRemoved={(it, pt) => chatRef.current?.requestObjectRemoval(it.id, it.content || '', pt.label, [pt.y, pt.x])} showPointLabels={showPointLabels} onDeletePointLocal={(iid, pid) => { const nextItems = items.map(it => it.id === iid ? { ...it, identifiedPoints: it.identifiedPoints?.filter(p => p.id !== pid) } : it); setItems(nextItems); commit(nextItems); }} onMovePoint={(iid, pid, ny, nx) => setItems(prev => prev.map(item => item.id === iid ? { ...item, identifiedPoints: item.identifiedPoints?.map(p => p.id === pid ? { ...p, y: ny, x: nx } : p) } : item))} onMovePointEnd={(iid, pid, from, to) => { const item = items.find(i => i.id === iid); if (item?.content) { const point = item.identifiedPoints?.find(p => p.id === pid); if (point) chatRef.current?.appendMovementDescription(iid, item.content, point.label, from, to); } }} isTextMode={editSubMode === 'text'} showGrid={showGrid} onZoomToFit={zoomToFit} onCaptureRegion={handleCaptureRegion} onFloatingAction={handleFloatingAction} expressionState={expressionState} setExpressionState={setExpressionState} inferenceState={inferenceState} setInferenceState={setInferenceState} currentEvolutionLevel={currentEvolutionLevel} captureState={captureState} onExitToolMode={() => setTool('select')} activePartId={activePartId} onPartSelect={setActivePartId} onCameraChange={(id, s) => handleUpdateItem(id, { spatialConfig: s })} onLoadParts={(id, p) => handleUpdateItem(id, { partList: p })} />
