={setEditTool} brushSize={brushSize} setBrushSize={setBrushSize} onApplyEdit={handleApplyEdit} onClearMask={() => canvasRef.current?.clearMask()} onJSONAnalysis={handleJSONAnalysis} isAnalyzingJSON={isAnalyzingJSON} onStartPickPoint={(nid, temp) => handleGenerate(nid, '__START_PICK_POINT__', { artisticLevel: temp })} isPickingPoint={isPickingPoint} currentEvolutionLevel={currentEvolutionLevel} isCncMode={isCncMode} setIsCncMode={setIsCncMode} onUpdatePoint={handleUpdatePoint} onClearAllPoints={handleClearAllPoints} onCommitPointChanges={handleCommitPointChanges} onAutoAlign={handleAutoAlignPoints} onClosePanel={() => setIsPropertiesPanelOpen(false)} onFloatingAction={handleFloatingAction} /> </div> </div> </div>
