  const selectedItem = selection.length === 1 ? items.find(it => it.id === selection[0]) || null : null;
  const selectedItems = items.filter(it => selection.includes(it.id));

  useEffect(() => {
    if (selectedItem?.type === ItemType.TEXT) {
