      setItems(prev => prev.map(it => { if (it.id === targetId) { const nextPoints = it.identifiedPoints?.map(p => { const match = alignment.find(a => a.targetId === p.id); return match ? { ...p, pairingId: match.sourceId, pairingSourceItemId: sourceId } : p; }); return { ...it, identifiedPoints: nextPoints }; } return it; }));
