                const val = matches ? Math.min(100, Math.max(0, parseInt(matches[0]))) / 100 : 0.5;
                setItems(currentItems => { const nextItems = currentItems.map(it => it.id === targetId ? { ...it, explodeFactor: val } : it); commit(nextItems); return nextItems; });
            }
