        }
        @media print {
          body * { visibility: hidden; }
          #root, .fixed { display: none !important; }
          .markdown-renderer { visibility: visible; width: 100%; position: absolute; left: 0; top: 0; }
          .markdown-renderer * { visibility: visible; }
        }
      `}</style>
    </>
  );
});

