      setIsAligning(false);
    }
  };

  const handleFontSizeChange = (size: number) => {
    if (selectedItem) {
      onUpdateItem(selectedItem.id, { fontSize: size });
    }
  };

  if (!selectedItem && !isTransplantMode) {
    return (
