                    <BoxIcon className="w-5 h-5 text-indigo-500"/>
                    <span className="font-black text-[11px] uppercase tracking-[0.2em] text-zinc-100">3D 对象编排器</span>
                </div>
                <button onClick={() => onDelete(selectedItem.id)} className="w-8 h-8 flex items-center justify-center rounded-lg hover:bg-red-500/10 text-zinc-500 hover:text-red-500 transition-all">
                    <TrashIcon className="w-4 h-4"/>
                </button>
            </div>

            <div className="space-y-4">
                <label className="text-[10px] font-black text-zinc-500 uppercase tracking-widest flex items-center gap-2">
                    <MagicCurveIcon className="w-3.5 h-3.5" /> Quick Expressions
                </label>
                <div className="grid grid-cols-2 gap-2">
                    {[
                        { id: 'reset', label: '还原状态', icon: <RotateCcwIcon className="w-3.5 h-3.5" /> },
                        { id: 'xray', label: 'X-Ray 透视', icon: <EyeIcon className="w-3.5 h-3.5" /> },
                        { id: 'clay', label: 'Clay 模式', icon: <BoxIcon className="w-3.5 h-3.5" /> },
                        { id: 'isolate', label: '孤立选中件', icon: <TargetIcon className="w-3.5 h-3.5" /> },
                    ].map(btn => (
                        <button 
                            key={btn.id}
                            onClick={() => handleExpressionAction(btn.id as any)}
                            className="flex items-center gap-2 py-3 px-4 bg-zinc-800/40 hover:bg-indigo-600/20 rounded-xl text-[10px] font-black uppercase tracking-widest border border-white/5 transition-all"
                        >
                            {btn.icon} {btn.label}
                        </button>
                    ))}
                </div>
            </div>

            <div className="space-y-4">
                <label className="text-[10px] font-black text-zinc-500 uppercase tracking-widest flex items-center gap-2">
                    <TerminalIcon className="w-3.5 h-3.5 text-indigo-400" /> Technical Drawing
                </label>
                <div className="grid grid-cols-2 gap-2">
                    <button 
                        onClick={() => onUpdateItem(selectedItem.id, { wireframeMode: !selectedItem.wireframeMode })}
                        className={`flex items-center gap-2 py-3 px-4 rounded-xl text-[10px] font-black uppercase tracking-widest border border-white/5 transition-all ${selectedItem.wireframeMode ? 'bg-indigo-600 text-white' : 'bg-zinc-800/40 text-zinc-400 hover:text-zinc-200'}`}
                    >
                        <RefreshIcon className="w-3.5 h-3.5" /> 线框模式
                    </button>
                    <button 
                        onClick={() => onUpdateItem(selectedItem.id, { showExplodeTrails: !selectedItem.showExplodeTrails })}
                        className={`flex items-center gap-2 py-3 px-4 rounded-xl text-[10px] font-black uppercase tracking-widest border border-white/5 transition-all ${selectedItem.showExplodeTrails ? 'bg-indigo-600 text-white' : 'bg-zinc-800/40 text-zinc-400 hover:text-zinc-200'}`}
                    >
                        <MagicCurveIcon className="w-3.5 h-3.5" /> 爆炸轨迹
                    </button>
                    <button 
                        onClick={() => onUpdateItem(selectedItem.id, { technicalCallouts: !selectedItem.technicalCallouts })}
                        className={`flex items-center gap-2 py-3 px-4 rounded-xl text-[10px] font-black uppercase tracking-widest border border-white/5 transition-all ${selectedItem.technicalCallouts ? 'bg-indigo-600 text-white' : 'bg-zinc-800/40 text-zinc-400 hover:text-zinc-200'}`}
                    >
                        <ListOrderedIcon className="w-3.5 h-3.5" /> 引线标注
                    </button>
                    <button 
                        onClick={() => onFloatingAction?.(selectedItem.id, 'generate_bom')}
                        className={`flex items-center gap-2 py-3 px-4 rounded-xl text-[10px] font-black uppercase tracking-widest border border-white/5 transition-all bg-zinc-800/40 text-zinc-400 hover:text-white`}
                    >
                        <FileIcon className="w-3.5 h-3.5" /> 生成 BOM 表
                    </button>
                </div>
            </div>

            <div className="space-y-6">
                <div className="space-y-4">
                    <div className="flex justify-between items-center px-1">
