                        <span className="text-indigo-400 font-mono text-[11px] font-black bg-indigo-500/10 px-2 py-0.5 rounded-md border border-indigo-500/20">{Math.round((selectedItem.knollingFactor || 0) * 100)}%</span>
                    </div>
                    <input 
                        type="range" min="0" max="1" step="0.01"
                        value={selectedItem.knollingFactor || 0}
                        onChange={(e) => onUpdateItem(selectedItem.id, { knollingFactor: Number(e.target.value) })}
                        className="w-full h-1 bg-zinc-800 rounded-lg appearance-none accent-indigo-500 cursor-pointer"
                    />
                </div>

                <div className="space-y-4">
                    <div className="flex justify-between items-center px-1">
                        <label className="text-[10px] font-black text-zinc-500 uppercase tracking-widest">物理爆炸强度</label>
                        <span className="text-indigo-400 font-mono text-[11px] font-black bg-indigo-500/10 px-2 py-0.5 rounded-md border border-indigo-500/20">{Math.round((selectedItem.explodeFactor || 0) * 100)}%</span>
                    </div>
                    <input 
                        type="range" min="0" max="1" step="0.01"
                        value={selectedItem.explodeFactor || 0}
                        onChange={(e) => onUpdateItem(selectedItem.id, { explodeFactor: Number(e.target.value) })}
                        className="w-full h-1 bg-zinc-800 rounded-lg appearance-none accent-indigo-500 cursor-pointer"
                    />
                </div>
            </div>

            <div className="space-y-3">
                <label className="text-[10px] font-black text-zinc-500 uppercase tracking-widest flex items-center gap-2">
                    <PaletteIcon className="w-3.5 h-3.5" /> Material Library (CMF)
                </label>
                <div className="grid grid-cols-4 gap-2">
                    {Object.entries(CMF_LIBRARY).map(([key, cmf]) => (
                        <button 
                            key={key}
                            onClick={() => handleApplyMaterial(undefined, key)}
                            className="group relative aspect-square rounded-xl overflow-hidden border border-white/5 hover:border-indigo-500 transition-all shadow-lg"
                            title={(cmf as any).label}
                        >
                            <div className="absolute inset-0" style={{ backgroundColor: (cmf as any).color, opacity: (cmf as any).opacity ?? 1 }} />
                            <div className="absolute inset-0 bg-gradient-to-tr from-black/40 to-white/10 opacity-60" />
                            <div className="absolute inset-0 opacity-0 group-hover:opacity-100 bg-black/40 flex items-center justify-center transition-opacity">
                                <CheckIcon className="w-4 h-4 text-white" />
                            </div>
                        </button>
                    ))}
                </div>
                {selectedItem.activePartId && (
                    <p className="text-[9px] text-zinc-600 font-bold uppercase tracking-tighter text-center">正在为 "{selectedItem.activePartId.slice(0, 15)}..." 应用材质</p>
                )}
            </div>

            <div className="space-y-3">
                <label className="text-[10px] font-black text-zinc-500 uppercase tracking-widest flex items-center gap-2">
                    <EyeIcon className="w-3.5 h-3.5" /> Camera Projection
                </label>
                <div className="flex bg-zinc-800/50 p-1 rounded-xl gap-1 border border-white/5">
                    <button 
                        onClick={() => onUpdateItem(selectedItem.id, { cameraMode: 'perspective' })}
                        className={`flex-1 py-2 text-[10px] font-black uppercase tracking-widest rounded-lg transition-all ${selectedItem.cameraMode !== 'orthographic' ? 'bg-indigo-600 text-white shadow-lg' : 'text-zinc-500 hover:text-zinc-300'}`}
                    >
                        透视 (Persp)
                    </button>
                    <button 
                        onClick={() => onUpdateItem(selectedItem.id, { cameraMode: 'orthographic' })}
                        className={`flex-1 py-2 text-[10px] font-black uppercase tracking-widest rounded-lg transition-all ${selectedItem.cameraMode === 'orthographic' ? 'bg-indigo-600 text-white shadow-lg' : 'text-zinc-500 hover:text-zinc-300'}`}
                    >
                        正交 (Ortho)
                    </button>
                </div>
            </div>

            <div className="space-y-4 relative">
                <div className="flex items-center justify-between">
                    <label className="text-[10px] font-black text-zinc-500 uppercase tracking-widest flex items-center gap-2">
                        <TerminalIcon className="w-3.5 h-3.5 text-indigo-400" /> Model Command Center
                    </label>
                    {isCommandFocused && (
                        <button className="animate-spin-slow p-1 text-zinc-600 hover:text-indigo-400 transition-colors">
                            <RefreshIcon className="w-3 h-3" />
                        </button>
                    )}
                </div>
                <div className="relative group">
                    <textarea 
                        ref={commandRef}
                        value={modelCommand}
                        onFocus={() => setIsCommandFocused(true)}
                        onBlur={() => setTimeout(() => setIsCommandFocused(false), 300)}
                        onChange={(e) => setModelCommand(e.target.value)}
                        onKeyDown={(e) => { if(e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); handleExecuteModelCommand(); } }}
                        className="w-full bg-[#111113] border border-zinc-800 rounded-xl px-4 py-3 text-[12px] h-20 focus:border-indigo-500/50 outline-none resize-none transition-all placeholder:text-zinc-700 shadow-inner"
                        placeholder="输入指令: '喷涂零件红色' 或 '隐藏指示灯'..."
                    />
                    <button 
                        onClick={() => handleExecuteModelCommand()}
                        className="absolute bottom-2 right-2 p-2 bg-indigo-600 hover:bg-indigo-500 text-white rounded-lg transition-all shadow-lg active:scale-95"
                    >
                        <ArrowIcon className="w-3.5 h-3.5" />
                    </button>
                </div>

                {isCommandFocused && (
                    <div className="absolute bottom-full mb-3 left-0 right-0 bg-[#1a1a1c] border border-zinc-800 rounded-2xl shadow-[0_-32px_64px_rgba(0,0,0,0.8)] overflow-hidden z-[100] animate-in fade-in slide-in-from-bottom-2 duration-300 pointer-events-auto">
                        <div className="p-3 bg-zinc-900/80 border-b border-white/5 flex items-center justify-between gap-2">
                            <div className="flex items-center gap-2">
                                <SparklesIcon className="w-3 h-3 text-indigo-400" />
                                <span className="text-[9px] font-black text-zinc-500 uppercase tracking-widest">智能意图解析建议</span>
                            </div>
                            <button className="text-[8px] font-black text-zinc-600 hover:text-zinc-400 transition-colors uppercase">Refresh</button>
                        </div>
                        <div className="max-h-64 overflow-y-auto no-scrollbar p-2 space-y-1 bg-[#1a1a1c]/95 backdrop-blur-xl">
                            {SUGGESTIONS.map(s => (
                                <button 
                                    key={s.label}
                                    onMouseDown={() => handleExecuteModelCommand(s.cmd)}
                                    className="w-full text-left px-3 py-2.5 rounded-lg hover:bg-indigo-600/10 hover:text-indigo-400 transition-all flex items-center justify-between group border border-transparent hover:border-indigo-500/20"
                                >
                                    <span className="text-[11px] font-bold">{s.label}</span>
                                    <span className="text-[9px] font-mono text-zinc-600 group-hover:text-indigo-500/50">{s.cmd}</span>
                                </button>
                            ))}
                            {relevantParts.length > 0 && (
                                <>
                                    <div className="h-px bg-white/5 my-2 mx-1" />
                                    <div className="px-3 py-1.5 text-[8px] font-black text-zinc-700 uppercase tracking-widest flex items-center gap-2">
                                        <BoxIcon className="w-2.5 h-2.5" /> 常用部件深度操作
                                    </div>
                                    <div className="grid grid-cols-1 gap-1 px-1">
                                        {relevantParts.map(p => (
                                            <div key={p} className="flex gap-1">
                                                <button 
                                                    onMouseDown={() => handleExecuteModelCommand(`隐藏零件 ${p}`)}
                                                    className="flex-1 text-left px-3 py-1.5 rounded-lg hover:bg-red-600/10 hover:text-red-400 transition-all text-[10px] font-bold truncate border border-white/2"
                                                >
                                                    🚫 隐藏 {p.slice(0, 12)}
                                                </button>
                                                <button 
                                                    onMouseDown={() => handleExecuteModelCommand(`喷涂零件 ${p} 拉丝铝`)}
                                                    className="flex-1 text-left px-3 py-1.5 rounded-lg hover:bg-indigo-600/10 hover:text-indigo-400 transition-all text-[10px] font-bold truncate border border-white/2"
                                                >
                                                    🎨 材质 {p.slice(0, 12)}
                                                </button>
                                            </div>
                                        ))}
                                    </div>
                                </>
                            )}
                        </div>
                    </div>
                )}
            </div>

            <div className="space-y-4">
                <div className="flex items-center justify-between">
                    <label className="text-[10px] font-black text-zinc-500 uppercase tracking-widest flex items-center gap-2">
                        <CameraIcon className="w-3.5 h-3.5" /> Perspective Manager
                    </label>
                    <button 
                        onClick={handleCaptureView}
                        className="p-1.5 bg-indigo-500/10 text-indigo-400 hover:bg-indigo-500/20 rounded-lg border border-indigo-500/20 transition-all"
                        title="捕获自定义视角"
                    >
                        <PlusIcon className="w-3.5 h-3.5" />
                    </button>
                </div>

                <div className="grid grid-cols-2 gap-2">
                    {standardViews.map(sv => (
                        <button 
                            key={sv.id}
                            onClick={() => handleApplyStandardView(sv.id, sv.config)}
