        const detailLevel = temperature > 1.2 ? "极其详尽且包含微观材质语义（如：带有磨砂纹理的阳极氧化铝拉丝边缘）" : (temperature > 0.6 ? "详细且带有材质修饰词（如：银色拉丝金属旋钮）" : "简洁明了（如：白色塑料按钮）");

