        if (pkg.items && Array.isArray(pkg.items)) { 
            resetHistory(pkg.items); if (pkg.view) setView(pkg.view); 
            if (pkg.recipes) { for (const r of pkg.recipes) await saveRecipe(r); setRecipeRefreshTrigger(prev => prev + 1); }
